class Circulo {
    private double raio;
    Circulo() { this(1.0); }
    Circulo(double raio) {
        if (!Double.isFinite(raio) || raio <= 0) {
            throw new IllegalArgumentException("Raio inválido");
        }
        this.raio = raio;
    }
    double area() { return Math.PI * raio * raio; }
}

